function nthTriangular(k){
  k=Math.floor(+k);
  if(isNaN(k)||k<0) return {error:'请输入非负整数 k'};
  return {value:k*(k+1)/2, k:k};
}
function isTriangular(n){
  n=Math.floor(Math.abs(+n));
  if(isNaN(n)||n<0) return {error:'请输入非负整数'};
  var k=Math.floor((Math.sqrt(8*n+1)-1)/2);
  var isT=(k*(k+1)/2)===n;
  return {value:n, isTriangular:isT, k:isT?k:-1};
}
var EXPORTS={nthTriangular:nthTriangular, isTriangular:isTriangular};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TriangularForgePure = EXPORTS; }
